public static void main(Args        _args)
{
    KCS_KBVRequestTable         requestTable;
    SalesQuotationTable         createdsalesQuotationTable;
    SalesQuotationTable         existsSalesQuotationTable;
    int                         Counter;

    while select requestTable
        where requestTable.KCS_KBVRequestStatus == KCS_KBVRequestStatus::InProcess
            exists join existsSalesQuotationTable
            where existsSalesQuotationTable.KCS_KBVRequestId == requestTable.KCS_KBVRequestID
            notexists join createdsalesQuotationTable
               where createdsalesQuotationTable.KCS_KBVRequestId == requestTable.KCS_KBVRequestID
                  && createdsalesQuotationTable.QuotationStatus == SalesQuotationStatus::Created
    {

        info(requestTable.KCS_KBVRequestID);
    }

    if (Box::yesNo('Wolles Sie die BV-Anforderungen aktualisieren?',DialogButton::No) == DialogButton::Yes)
    {
        while select requestTable
        where requestTable.KCS_KBVRequestStatus == KCS_KBVRequestStatus::InProcess
            exists join existsSalesQuotationTable
            where existsSalesQuotationTable.KCS_KBVRequestId == requestTable.KCS_KBVRequestID
            notexists join createdsalesQuotationTable
               where createdsalesQuotationTable.KCS_KBVRequestId == requestTable.KCS_KBVRequestID
                  && createdsalesQuotationTable.QuotationStatus == SalesQuotationStatus::Created
        {
            counter ++;
            requestTable.selectForUpdate(true);
            requestTable.KCS_KBVRequestStatus = KCS_KBVRequestStatus::Answered;
            ttsbegin;
            requestTable.doUpdate();
            ttscommit;
        }
    }

    info(strFmt('%1  Datensätze wurden aktualisiert.',int2Str(counter)));
}
